__NUXT_JSONP__("/inclusion/publicaciones/evidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"evidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",title:"Evidence to Integrate Gender Perspective in Disaster Risk Management in Mexico",date:"2025-10-14T17:25:28.004Z",img:"https:\u002F\u002Fucarecdn.com\u002F21a776b0-1697-4335-98bb-c95ebc391e83\u002F","img-alt":"Disaster Risk Management in Mexico",autor:"Ethos",category:d,extracto:"We want to generate quantitative evidence to measure and understand the differentiated impacts of disasters on women, including those related to gender-based violence, highlight the need to include this information in the National Disaster Risk Management strategies and share it with key stakeholders and * Promote evidence-based decision-making with a gender perspective in the development of DRM strategies.",file:"https:\u002F\u002Fucarecdn.com\u002Fe1ff98bf-bf12-48af-8385-f6abec559c7b\u002F",toc:[],body:{type:e,children:[{type:c,tag:f,props:{},children:[{type:a,value:"The objectives are:"}]},{type:a,value:b},{type:c,tag:"ul",props:{},children:[{type:a,value:b},{type:c,tag:i,props:{},children:[{type:a,value:"Generate quantitative evidence to measure and understand the differentiated impacts of disasters on women, including those related to gender-based violence (as one of the most frequently mentioned effects in the literature review)."}]},{type:a,value:b},{type:c,tag:i,props:{},children:[{type:a,value:"Highlight the need to include this information in the National Disaster Risk Management strategies and share it with key stakeholders."}]},{type:a,value:b},{type:c,tag:i,props:{},children:[{type:a,value:"Promote evidence-based decision-making with a gender perspective in the development of DRM strategies."}]},{type:a,value:b}]}]},dir:g,path:"\u002Fpublicaciones\u002Fevidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",extension:h,createdAt:"2025-11-25T01:24:03.288Z",updatedAt:"2025-11-25T01:24:03.289Z"},publicaciones:[{slug:"cuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",title:"Cuidados para la primera infancia: Recomendaciones hacia la conformación del Sistema Nacional de Cuidados",date:"2025-03-18T14:41:00.000Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffca2a0ef-b4dd-4e5f-9a7f-c17d24f27d70\u002F-\u002Fcrop\u002F1047x1377\u002F18,15\u002F-\u002Fpreview\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos, Early Institute y el Centro de Investigación Económica y Presupuestaria ",category:d,extracto:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez. ",file:"https:\u002F\u002Fucarecdn.com\u002Fb2c423fb-64a1-42e7-9f85-07fff85a84e8\u002F",toc:[],body:{type:e,children:[{type:c,tag:f,props:{},children:[{type:a,value:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fcuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",extension:h,createdAt:j,updatedAt:j},{slug:"el_seguro_popular_de_salud_en_mexico_efectos_sobre_la_informalidad",title:"EL SEGURO POPULAR DE SALUD EN MÉXICO: EFECTOS SOBRE LA INFORMALIDAD",date:"2011-02-20T22:12:41.202Z",img:"https:\u002F\u002Fucarecdn.com\u002F94fc3ac6-01bd-4d71-aa0b-962d2222f676\u002F",autor:"Alicia Santana, Liliana Alvarado.",category:d,extracto:k,file:"https:\u002F\u002Fucarecdn.com\u002Ff6541ea7-f186-4386-9b30-2adb2f3f2d06\u002F",toc:[],body:{type:e,children:[{type:a,value:b},{type:c,tag:f,props:{},children:[{type:a,value:k}]},{type:a,value:b}]},dir:g,path:"\u002Fpublicaciones\u002Fel_seguro_popular_de_salud_en_mexico_efectos_sobre_la_informalidad",extension:h,createdAt:"2023-06-19T05:12:04.594Z",updatedAt:"2022-08-24T22:31:42.864Z"},{slug:"el_seguro_popular_de_salud_en_mexico_posibles_efectos_sobre_la_economia_informal",title:"El Seguro Popular de salud en México: posibles efectos sobre la economía informal",date:"2011-02-01T15:47:13.927Z",img:"https:\u002F\u002Fucarecdn.com\u002F9fad819f-509d-482c-a742-2390b145e21a\u002F",autor:"Alicia Santana Cartas, Liliana Alvarado Baena, Stephen Birtwistle y Carlos Demian Rivera Saldaña",category:d,extracto:"La economía informal es un fenómeno en la historia de México que ha adquirido importancia en las últimas décadas. Consecuencia de ello es la preocupación de ciertos sectores de la sociedad por aminorar su peso dentro de la economía.",file:"https:\u002F\u002Fucarecdn.com\u002Fb6bdcf0a-3d62-4d08-b4fc-be722d29eec3\u002F",toc:[],body:{type:e,children:[{type:a,value:b},{type:c,tag:f,props:{},children:[{type:a,value:"La economía informal es un fenómeno en la historia de México que ha adquirido importancia en las últimas décadas. Consecuencia de ello es la preocupación de ciertos sectores de la sociedad por aminorar su peso dentro de la economía. Los estudios que analizan a la informalidad coinciden en que el desempeño económico, las cargas tributarias, las excesivas regulaciones, así como el bajo capital humano de los trabajadores, son los principales factores que causan y fomentan la informalidad. Por su parte, la evasión de impuestos, el incumplimiento de la regulación gubernamental y una baja productividad, han sido identificados como sus principales resultados. En este documento se desarrolla a profundidad la relación que guarda la informalidad con el Seguro Popular (SP). Lo anterior, debido a la trascendencia que tiene este tema en distintos rubros como son las finanzas públicas y la salud"}]},{type:a,value:b}]},dir:g,path:"\u002Fpublicaciones\u002Fel_seguro_popular_de_salud_en_mexico_posibles_efectos_sobre_la_economia_informal",extension:h,createdAt:"2023-06-19T05:12:04.602Z",updatedAt:"2022-08-28T23:28:14.353Z"}]}],fetch:{},mutations:[]}}("text","\n","element","inclusion","root","p","\u002Fpublicaciones",".md","li","2025-04-23T06:21:15.398Z","Cambios en el empleo informal debido al programa Seguro Popular de Salud.")));